/* Rentcam CMS + analytics */
(function(){
  const SB='https://xleceiffuopioeguniwj.supabase.co';
  const KEY='sb_publishable_POksYryhG_mkFbs7N0fjKQ_4dUim7Ex';
  const H={apikey:KEY,'Content-Type':'application/json'};
  const sid=sessionStorage.getItem('rentcam_sid')||(()=>{const v=(crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random());sessionStorage.setItem('rentcam_sid',v);return v})();
  let cfg=null, auth=null, reportTimer=null;
  const esc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  const json=(v,f)=>{try{return JSON.parse(v)}catch(e){alert(f||'Format JSON tidak valid');throw e}};

  async function api(path,opt={}){const r=await fetch(SB+path,{...opt,headers:{...H,...(opt.headers||{})}});if(!r.ok){const t=await r.text();throw new Error(t||r.statusText)}if(r.status===204)return null;return r.json()}
  async function getConfig(){try{const d=await api('/rest/v1/rentcam_cms_config?id=eq.1&select=config');cfg=d?.[0]?.config||{};window.RENTCAM_CMS_CONFIG=cfg;applyConfig();document.dispatchEvent(new CustomEvent('rentcam-cms-updated',{detail:cfg}));return cfg}catch(e){console.warn('CMS config',e);cfg={};return cfg}}
  function authHeaders(){return auth?.access_token?{Authorization:'Bearer '+auth.access_token}:{}}
  async function saveConfig(){if(!auth?.access_token) return alert('Login admin dulu');await api('/rest/v1/rentcam_cms_config?id=eq.1',{method:'PATCH',headers:{...authHeaders(),Prefer:'return=minimal'},body:JSON.stringify({config:cfg})});window.RENTCAM_CMS_CONFIG=cfg;applyConfig();document.dispatchEvent(new CustomEvent('rentcam-cms-updated',{detail:cfg}));toast('Pengaturan tersimpan')}
  async function login(email,password){const d=await api('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email,password})});auth=d;localStorage.setItem('rentcam_cms_auth',JSON.stringify(d));renderCMS()}
  function logout(){auth=null;localStorage.removeItem('rentcam_cms_auth');clearInterval(reportTimer);renderCMS()}
  function toast(t){const d=document.createElement('div');d.textContent=t;d.className='cms-toast';document.body.appendChild(d);setTimeout(()=>d.remove(),1800)}

  async function track(type,path=location.pathname,productId=null){if(path.startsWith('/cms'))return;try{await api('/rest/v1/rentcam_events',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({event_type:type,path,product_id:productId,session_id:sid,meta:{ua:navigator.userAgent.slice(0,180)}})})}catch(e){}}
  async function ping(){if(location.pathname.startsWith('/cms'))return;try{await api('/rest/v1/rentcam_presence?on_conflict=session_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({session_id:sid,path:location.pathname,last_seen:new Date().toISOString()})})}catch(e){}}
  const nativePush=history.pushState.bind(history);history.pushState=function(a,b,u){const r=nativePush(a,b,u);setTimeout(()=>{const p=location.pathname;track('page_view',p);const m=p.match(/^\/produk\/([^/?#]+)/);if(m)track('product_click',p,decodeURIComponent(m[1]));applyConfig();if(p==='/cms'||p.startsWith('/cms/'))renderCMS()},0);return r};
  addEventListener('popstate',()=>{setTimeout(()=>{track('page_view');applyConfig();if(location.pathname.startsWith('/cms'))renderCMS()},0)});
  track('page_view');ping();setInterval(ping,30000);

  function applyConfig(){if(!cfg)return;const g=cfg.general||{},hp=cfg.homepage||{};
    document.querySelectorAll('.header .brand span,.footer .brand').forEach(x=>{if(g.siteName)x.textContent=g.siteName});
    const fp=document.querySelector('.footer .footgrid>div:first-child p');if(fp&&g.footerText)fp.textContent=g.footerText;
    const wa=[...document.querySelectorAll('.footer a')].find(a=>/WhatsApp/i.test(a.textContent||''));if(wa&&g.whatsapp){wa.href='https://wa.me/'+String(g.whatsapp).replace(/\D/g,'');wa.target='_blank';wa.onclick=null}
    const hero=document.querySelector('#app .hero');if(hero)hero.style.display=hp.heroEnabled===false?'none':'';
    [['camera',hp.productsCamera],['lighting',hp.productsLighting],['audio',hp.productsAudio],['package',hp.productsPackage]].forEach(([k,n])=>{if(!n)return;document.querySelectorAll('#app .home-'+k+' .home-category-card').forEach((c,i)=>c.style.display=i<Number(n)?'':'none')});
    try{if(typeof P!=='undefined'){const o=cfg.productOverrides||{};Object.keys(o).forEach(id=>{const p=P.find(x=>x.id===id);if(p){const v=o[id];if(v.name)p.name=v.name;if(v.category)p.cat=v.category;if(v.image)p.img=v.image;if(v.price!==''&&v.price!=null){p.price=Number(v.price)||p.price;p.priceAud=Number(v.price)||p.priceAud}p._cmsActive=v.active!==false}})}}catch(e){}
    const ov=cfg.productOverrides||{};document.querySelectorAll('#app .pcard').forEach(c=>{const txt=c.getAttribute('onclick')||'';const m=txt.match(/\/produk\/([^'\")]+)/);if(m&&ov[m[1]]?.active===false)c.style.display='none'});
    try{if((cfg.banners||[]).length&&typeof SL!=='undefined'){SL.splice(0,SL.length,...cfg.banners.map(b=>({ey:b.ey||'RENTCAM',t:b.title||'',p:b.text||'',img:b.image||''})))}}catch(e){}
  }
  new MutationObserver(()=>applyConfig()).observe(document.documentElement,{childList:true,subtree:true});
  getConfig();

  function styles(){if(document.getElementById('rentcam-cms-style'))return;const s=document.createElement('style');s.id='rentcam-cms-style';s.textContent=`
  #app .cms{min-height:calc(100vh - 86px);background:#f4f5f7;padding:24px 0 70px;color:#111}.cms *{box-sizing:border-box}.cms .wrap{width:min(1320px,calc(100% - 28px));margin:auto}.cms-login{max-width:440px;margin:70px auto;background:#fff;border:1px solid #e6e6e6;border-radius:22px;padding:28px;box-shadow:0 18px 50px rgba(0,0,0,.06)}.cms-login h1{margin:0 0 8px;font-size:28px}.cms-login p{color:#777;font-size:13px;margin:0 0 22px}.cms input,.cms textarea,.cms select{width:100%;border:1px solid #ddd;border-radius:12px;background:#fff;padding:12px 13px;font:inherit;font-size:13px;outline:none}.cms textarea{min-height:180px;resize:vertical;font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.cms label{display:block;font-size:11px;font-weight:800;color:#555;margin:12px 0 6px}.cms button{border:0;border-radius:12px;background:#111;color:#fff;padding:12px 15px;font-weight:800;cursor:pointer}.cms button.light{background:#fff;color:#111;border:1px solid #ddd}.cms-shell{display:grid;grid-template-columns:220px minmax(0,1fr);gap:18px}.cms-side{background:#111;color:#fff;border-radius:20px;padding:18px;position:sticky;top:104px;height:max-content}.cms-brand{font-size:20px;font-weight:900;margin:4px 0 18px}.cms-nav button{display:block;width:100%;text-align:left;background:transparent;border:0;color:#aaa;padding:11px 12px;border-radius:10px}.cms-nav button.on,.cms-nav button:hover{background:#232323;color:#fff}.cms-main{min-width:0}.cms-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.cms-top h1{margin:0;font-size:30px;letter-spacing:-.04em}.cms-card{background:#fff;border:1px solid #e6e6e6;border-radius:18px;padding:18px;margin-bottom:14px}.cms-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.cms-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.cms-metric{background:#fff;border:1px solid #e7e7e7;border-radius:16px;padding:18px}.cms-metric b{font-size:27px;display:block}.cms-metric span{font-size:10px;text-transform:uppercase;color:#888;letter-spacing:.08em}.cms-table{width:100%;border-collapse:collapse;font-size:12px}.cms-table th,.cms-table td{padding:10px;border-bottom:1px solid #eee;text-align:left}.cms-row-actions{display:flex;gap:8px;flex-wrap:wrap}.cms-product-editor{display:grid;grid-template-columns:1fr 1fr;gap:10px}.cms-help{font-size:11px;color:#888;line-height:1.5}.cms-toast{position:fixed;right:18px;top:100px;z-index:9999;background:#111;color:#fff;padding:12px 16px;border-radius:12px;font-size:12px;font-weight:800}.cms-online{display:inline-flex;align-items:center;gap:7px}.cms-online:before{content:'';width:8px;height:8px;border-radius:50%;background:#1fc36a;box-shadow:0 0 0 5px rgba(31,195,106,.12)}
  @media(max-width:850px){.cms-shell{grid-template-columns:1fr}.cms-side{position:static}.cms-nav{display:flex;overflow:auto;gap:6px}.cms-nav button{width:auto;white-space:nowrap}.cms-metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){#app .cms{padding-top:14px}.cms-grid,.cms-product-editor{grid-template-columns:1fr}.cms-top{align-items:flex-start;gap:10px}.cms-top h1{font-size:24px}.cms-card{padding:14px}.cms-login{margin:25px auto}.cms-metrics{gap:8px}.cms-metric{padding:14px}.cms-metric b{font-size:22px}}
  `;document.head.appendChild(s)}
  let tab='dashboard';
  function loginView(){return `<section class="cms"><div class="wrap"><div class="cms-login"><h1>Rentcam CMS</h1><p>Login dengan akun admin Supabase untuk mengubah website dan melihat report.</p><label>Email</label><input id="cmsEmail" type="email" autocomplete="username"><label>Password</label><input id="cmsPassword" type="password" autocomplete="current-password"><div style="height:14px"></div><button style="width:100%" id="cmsLoginBtn">Masuk CMS</button></div></div></section>`}
  function nav(){return ['dashboard','general','homepage','banners','products','portfolio','articles','footer','report'].map(x=>`<button data-tab="${x}" class="${tab===x?'on':''}">${({dashboard:'Dashboard',general:'General',homepage:'Homepage',banners:'Banner',products:'Produk',portfolio:'Portfolio',articles:'Artikel',footer:'Footer',report:'Report'})[x]}</button>`).join('')}
  function generalTab(){const g=cfg.general||{};return `<div class="cms-card"><div class="cms-grid"><div><label>Nama Website</label><input data-c="general.siteName" value="${esc(g.siteName||'Rentcam')}"></div><div><label>Tagline</label><input data-c="general.tagline" value="${esc(g.tagline||'')}"></div><div><label>WhatsApp</label><input data-c="general.whatsapp" value="${esc(g.whatsapp||'')}"></div><div><label>Footer Text</label><input data-c="general.footerText" value="${esc(g.footerText||'')}"></div></div></div>`}
  function homepageTab(){const h=cfg.homepage||{};return `<div class="cms-card"><label><input style="width:auto" type="checkbox" data-bool="homepage.heroEnabled" ${h.heroEnabled!==false?'checked':''}> Tampilkan hero/banner utama</label><div class="cms-grid"><div><label>Jumlah Kamera</label><input type="number" data-num="homepage.productsCamera" value="${h.productsCamera||8}"></div><div><label>Jumlah Lighting</label><input type="number" data-num="homepage.productsLighting" value="${h.productsLighting||8}"></div><div><label>Jumlah Audio</label><input type="number" data-num="homepage.productsAudio" value="${h.productsAudio||8}"></div><div><label>Jumlah Paket</label><input type="number" data-num="homepage.productsPackage" value="${h.productsPackage||8}"></div></div></div>`}
  function jsonTab(key,title,help){return `<div class="cms-card"><h3>${title}</h3><p class="cms-help">${help}</p><textarea id="json_${key}">${esc(JSON.stringify(cfg[key]||[],null,2))}</textarea><div style="height:10px"></div><button data-jsonsave="${key}">Terapkan Data</button></div>`}
  function productTab(){let options='';try{if(typeof P!=='undefined')options=P.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} — ${esc(p.id)}</option>`).join('')}catch(e){}const o=cfg.productOverrides||{};return `<div class="cms-card"><h3>Edit Produk</h3><p class="cms-help">Pilih produk lalu override nama, harga, kategori, gambar, atau status tampil. Data asli tetap aman dan bisa dikembalikan dengan menghapus override.</p><label>Produk</label><select id="cmsProductId"><option value="">Pilih produk…</option>${options}</select><div class="cms-product-editor"><div><label>Nama</label><input id="cmsProductName"></div><div><label>Harga</label><input id="cmsProductPrice" type="number"></div><div><label>Kategori</label><input id="cmsProductCategory"></div><div><label>URL Gambar</label><input id="cmsProductImage"></div></div><label><input style="width:auto" id="cmsProductActive" type="checkbox" checked> Produk aktif / tampil</label><div class="cms-row-actions"><button id="cmsSaveProduct">Simpan Override</button><button class="light" id="cmsDeleteProduct">Hapus Override</button></div></div><div class="cms-card"><h3>Override Aktif</h3><table class="cms-table"><thead><tr><th>ID</th><th>Nama</th><th>Harga</th><th>Status</th></tr></thead><tbody>${Object.entries(o).map(([id,v])=>`<tr><td>${esc(id)}</td><td>${esc(v.name||'-')}</td><td>${esc(v.price||'-')}</td><td>${v.active===false?'Hidden':'Active'}</td></tr>`).join('')||'<tr><td colspan="4">Belum ada override.</td></tr>'}</tbody></table></div>`}
  function dashboardTab(){return `<div class="cms-card"><h3>Rentcam CMS</h3><p class="cms-help">Semua pengaturan utama website dikelola dari sini. Gunakan menu Produk untuk override katalog, Portfolio/Artikel untuk konten, dan Report untuk traffic.</p></div><div id="cmsMetrics" class="cms-metrics"><div class="cms-metric"><b>…</b><span>Online</span></div><div class="cms-metric"><b>…</b><span>Views 24h</span></div><div class="cms-metric"><b>…</b><span>Product Clicks</span></div><div class="cms-metric"><b>…</b><span>Views 7d</span></div></div>`}
  function reportTab(){return `<div id="cmsReport"><div class="cms-card">Memuat report…</div></div>`}
  function bodyForTab(){if(tab==='dashboard')return dashboardTab();if(tab==='general')return generalTab();if(tab==='homepage')return homepageTab();if(tab==='banners')return jsonTab('banners','Banner Homepage','Format tiap item: {"ey":"PROMO","title":"Judul","text":"Deskripsi","image":"https://..."}');if(tab==='products')return productTab();if(tab==='portfolio')return jsonTab('portfolio','Portfolio','Array item: id, title, cat, year, camera, lens, img, desc.');if(tab==='articles')return jsonTab('articles','Artikel','Array item: id, title, cat, date, read, img, excerpt, body.');if(tab==='footer')return generalTab();return reportTab()}
  function adminView(){return `<section class="cms"><div class="wrap cms-shell"><aside class="cms-side"><div class="cms-brand">Rentcam CMS</div><div class="cms-nav">${nav()}</div><div style="height:12px"></div><button class="light" id="cmsLogout" style="width:100%">Logout</button></aside><main class="cms-main"><div class="cms-top"><div><h1>${({dashboard:'Dashboard',general:'General',homepage:'Homepage',banners:'Banner',products:'Produk',portfolio:'Portfolio',articles:'Artikel',footer:'Footer',report:'Report'})[tab]}</h1></div><button id="cmsSaveAll">Simpan</button></div>${bodyForTab()}</main></div></section>`}
  function setPath(obj,path,val){const a=path.split('.');let x=obj;for(let i=0;i<a.length-1;i++)x=x[a[i]]||(x[a[i]]={});x[a[a.length-1]]=val}
  async function loadReport(){if(!auth?.access_token)return;const since30=new Date(Date.now()-30*864e5).toISOString(),since2=new Date(Date.now()-120000).toISOString();try{const [ev,pr]=await Promise.all([api('/rest/v1/rentcam_events?select=event_type,path,product_id,created_at&created_at=gte.'+encodeURIComponent(since30)+'&order=created_at.desc&limit=2000',{headers:authHeaders()}),api('/rest/v1/rentcam_presence?select=session_id,path,last_seen&last_seen=gte.'+encodeURIComponent(since2),{headers:authHeaders()})]);const now=Date.now(),d1=now-864e5,d7=now-7*864e5;const pv24=ev.filter(x=>x.event_type==='page_view'&&Date.parse(x.created_at)>=d1).length,pc24=ev.filter(x=>x.event_type==='product_click'&&Date.parse(x.created_at)>=d1).length,pv7=ev.filter(x=>x.event_type==='page_view'&&Date.parse(x.created_at)>=d7).length;const count=(arr,key,filter)=>Object.entries(arr.filter(filter||(()=>true)).reduce((a,x)=>{const k=x[key]||'-';a[k]=(a[k]||0)+1;return a},{})).sort((a,b)=>b[1]-a[1]).slice(0,10);const tp=count(ev,'product_id',x=>x.event_type==='product_click'&&x.product_id),pg=count(ev,'path',x=>x.event_type==='page_view'&&x.path);const html=`<div class="cms-metrics"><div class="cms-metric"><b class="cms-online">${pr.length}</b><span>Online sekarang</span></div><div class="cms-metric"><b>${pv24}</b><span>Views 24h</span></div><div class="cms-metric"><b>${pc24}</b><span>Product clicks 24h</span></div><div class="cms-metric"><b>${pv7}</b><span>Views 7d</span></div></div><div class="cms-grid" style="margin-top:14px"><div class="cms-card"><h3>Top Produk</h3><table class="cms-table">${tp.map(x=>`<tr><td>${esc(x[0])}</td><td><b>${x[1]}</b></td></tr>`).join('')||'<tr><td>Belum ada data</td></tr>'}</table></div><div class="cms-card"><h3>Top Halaman</h3><table class="cms-table">${pg.map(x=>`<tr><td>${esc(x[0])}</td><td><b>${x[1]}</b></td></tr>`).join('')||'<tr><td>Belum ada data</td></tr>'}</table></div></div><div class="cms-card"><h3>Aktivitas Terbaru</h3><table class="cms-table"><thead><tr><th>Event</th><th>Path / Produk</th><th>Waktu</th></tr></thead><tbody>${ev.slice(0,30).map(x=>`<tr><td>${esc(x.event_type)}</td><td>${esc(x.product_id||x.path||'-')}</td><td>${new Date(x.created_at).toLocaleString('id-ID')}</td></tr>`).join('')}</tbody></table></div>`;const r=document.getElementById('cmsReport');if(r)r.innerHTML=html;const m=document.getElementById('cmsMetrics');if(m)m.innerHTML=html.match(/<div class="cms-metrics">([\s\S]*?)<\/div><div class="cms-grid"/)?.[1]||m.innerHTML}catch(e){const r=document.getElementById('cmsReport');if(r)r.innerHTML='<div class="cms-card">Gagal memuat report: '+esc(e.message)+'</div>'}}
  function bindCMS(){document.querySelectorAll('.cms-nav [data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderCMS()});const lo=document.getElementById('cmsLogout');if(lo)lo.onclick=logout;const sb=document.getElementById('cmsSaveAll');if(sb)sb.onclick=saveConfig;document.querySelectorAll('[data-c]').forEach(i=>i.oninput=()=>setPath(cfg,i.dataset.c,i.value));document.querySelectorAll('[data-num]').forEach(i=>i.oninput=()=>setPath(cfg,i.dataset.num,Number(i.value)));document.querySelectorAll('[data-bool]').forEach(i=>i.onchange=()=>setPath(cfg,i.dataset.bool,i.checked));document.querySelectorAll('[data-jsonsave]').forEach(b=>b.onclick=()=>{cfg[b.dataset.jsonsave]=json(document.getElementById('json_'+b.dataset.jsonsave).value);toast('Data diterapkan, klik Simpan')});const sel=document.getElementById('cmsProductId');if(sel){sel.onchange=()=>{const id=sel.value,v=(cfg.productOverrides||{})[id]||{};let p=null;try{p=typeof P!=='undefined'?P.find(x=>x.id===id):null}catch(e){};document.getElementById('cmsProductName').value=v.name||p?.name||'';document.getElementById('cmsProductPrice').value=v.price??p?.priceAud??p?.price??'';document.getElementById('cmsProductCategory').value=v.category||p?.cat||'';document.getElementById('cmsProductImage').value=v.image||p?.img||'';document.getElementById('cmsProductActive').checked=v.active!==false};document.getElementById('cmsSaveProduct').onclick=()=>{const id=sel.value;if(!id)return alert('Pilih produk');cfg.productOverrides=cfg.productOverrides||{};cfg.productOverrides[id]={name:document.getElementById('cmsProductName').value,price:Number(document.getElementById('cmsProductPrice').value)||'',category:document.getElementById('cmsProductCategory').value,image:document.getElementById('cmsProductImage').value,active:document.getElementById('cmsProductActive').checked};renderCMS();toast('Override diterapkan, klik Simpan')};document.getElementById('cmsDeleteProduct').onclick=()=>{if(sel.value&&cfg.productOverrides){delete cfg.productOverrides[sel.value];renderCMS()}}}if(tab==='report'||tab==='dashboard'){loadReport();clearInterval(reportTimer);reportTimer=setInterval(loadReport,30000)}}
  async function renderCMS(){if(!location.pathname.startsWith('/cms'))return;styles();const app=document.getElementById('app');if(!app)return;if(!cfg)await getConfig();if(!auth){try{auth=JSON.parse(localStorage.getItem('rentcam_cms_auth')||'null')}catch(e){}}app.innerHTML=auth?.access_token?adminView():loginView();if(!auth?.access_token){const b=document.getElementById('cmsLoginBtn');if(b)b.onclick=async()=>{b.disabled=true;b.textContent='Masuk…';try{await login(document.getElementById('cmsEmail').value,document.getElementById('cmsPassword').value)}catch(e){alert('Login gagal. Periksa email/password akun Supabase.');b.disabled=false;b.textContent='Masuk CMS'}}}else bindCMS();scrollTo(0,0)}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>{if(location.pathname.startsWith('/cms'))renderCMS()});else if(location.pathname.startsWith('/cms'))renderCMS();
})();